INSERT INTO cases VALUES(26,'TX-26-00992','162nd District Court','GINSBERG, CARL','2026-05-19','OPEN','TAX DELINQUENCY','MISAEL RIVERA MARTINEZ','[{"name": "MISAEL RIVERA MARTINEZ", "address": "209 W. Ridgewood Drive, Garland, TX 75041", "serviceStatus": "served", "serviceMethod": "Constable", "isInRemOnly": false, "notes": "Primary defendant (In Personam). Executed citation 06/16/2026. Filed general denial answer 06/09/2026."}, {"name": "KEN MY LUONG", "address": "683 E. Muirfield Road, Garland, TX 75044", "serviceStatus": "served", "serviceMethod": "Constable", "isInRemOnly": true, "notes": "In Rem Only defendant. Executed citation 06/04/2026."}, {"name": "RESOLUTION FINANCE, LLC", "address": "By serving Registered Agent, Matt T. Longhofer, or any other officer or agent authorized to accept service, 4100 Alpha Road, Suite 670, Dallas, TX 75244", "serviceStatus": "served", "serviceMethod": "Constable", "isInRemOnly": true, "notes": "In Rem Only defendant. Executed citation 06/23/2026."}]','',NULL,'43270','LGBS (Linebarger)','REECE, LINDA D.',5895.3599999999992675,2024,'[2024, 2025]',3,0,0,'[]',0,0,0,'','medium',NULL,NULL,'none',NULL,0,'2027-01-27',NULL,NULL,NULL,'dallas',NULL,'[{"entity": "GARLAND INDEPENDENT SCHOOL DISTRICT", "taxAmt": 4154.62, "penaltyInterest": 1740.74, "total": 5895.36}]',replace('# ACQUISITION INTELLIGENCE MEMO\n**Case TX-26-00992 | 209 W. Ridgewood Drive, Garland, TX 75041**\n**Account #43270 | Defendant: MISAEL RIVERA MARTINEZ**\n**Date: January 2027 | Analyst: Senior Acquisitions**\n\n---\n\n## 1. PROPERTY & OWNER SITUATION\n\nDCAD Account #43270 at 209 W. Ridgewood Drive sits in an established Garland residential neighborhood near Firewheel Town Center. Without access to complete DCAD records in the case file, the presence of multiple interested parties—specifically KEN MY LUONG at a separate Garland address (683 E. Muirfield) and RESOLUTION FINANCE, LLC—suggests this is a distressed note situation or disputed ownership transfer. Luong''s involvement as an In Rem defendant at a different address indicates he may hold a lien, deed interest, or be a prior owner who failed to properly convey title to Martinez. Resolution Finance LLC, a Dallas-based entity served at 4100 Alpha Road Suite 670, typically operates as a note buyer or hard money lender, pointing to an underlying private financing arrangement that Martinez likely defaulted on beyond just property taxes. The $5,895.36 filing amount for only 2024-2025 tax years is manageable, suggesting the property has reasonable appraised value (likely $140K-$180K range based on typical Garland GISD tax rates of ~2.9%). This is a **structure play with title complexity**—the physical asset has value, but the ownership chain is contaminated. Martinez filed a general denial answer on 06/09/2026, seven days before he was even formally served on 06/16/2026, indicating either attorney representation or prior knowledge of the filing, which adds another layer of sophistication suggesting he''s fighting to preserve equity, not just squatting.\n\n## 2. FINANCIAL PICTURE\n\nThe $5,895.36 filing amount breaks down as $4,154.62 base tax to Garland ISD plus $1,740.74 in penalties and interest—a 41.9% penalty load that indicates these 2024-2025 taxes went unpaid immediately upon assessment. By January 2027, the live balance has grown to approximately **$6,400-$6,600** with continuing penalty accrual at 12% annually plus 1% monthly collection fees. The two-year delinquency on what should be a modest tax bill ($2,077/year base) on a property likely worth $150K-$170K creates a debt-to-value ratio under 4','\n',char(10)),NULL,'pre_judgment',NULL,NULL,NULL,NULL,'2026-07-01T23:57:12.499163','2026-07-07T12:40:26.501156','2026-07-07T12:40:26.501156',1,'individual','high','','');
INSERT INTO cases VALUES(27,'TX-26-00993','160th District Court','GINSBERG, CARL','2026-05-19','OPEN','TAX DELINQUENCY','ELIZABETH ORTALEJO','[{"name": "ELIZABETH ORTALEJO", "address": "1607 Denton Drive, Carrollton, TX 75006", "serviceStatus": "unserved", "serviceMethod": "Constable #4", "isInRemOnly": false, "notes": "Primary defendant, in personam"}, {"name": "ALEX RAFAEL ORTALEJO ESPINO", "address": "1607 Denton Drive, Carrollton, TX 75006", "serviceStatus": "unserved", "serviceMethod": "Constable #4", "isInRemOnly": false, "notes": "Co-defendant"}]','1607 N. Denton Drive, City of Carrollton, Texas',NULL,'65051925510190000','LGBS (Linebarger)','REECE, LINDA D.',4430.1499999999993661,2024,'[2024, 2025]',2,0,0,'[]',0,0,0,'Citations issued 05/26/2026 but both defendants remain unserved','low',NULL,NULL,'none',NULL,0,'2027-01-27',NULL,NULL,NULL,'dallas',NULL,'[{"entity": "CARROLLTON-FARMERS BRANCH INDEPENDENT SCHOOL DISTRICT", "taxAmt": 2773.86, "penaltyInterest": 1306.29, "total": 4080.15}]',replace('# ACQUISITION INTELLIGENCE MEMO\n**PC Peak Development – Priority Foreclosure Analysis**\n\n**Case:** TX-26-00993 | **Property:** 1607 N. Denton Drive, Carrollton, TX 75006  \n**Analyst Date:** January 2027 | **Classification:** HIGH-PRIORITY STRUCTURE PLAY\n\n---\n\n## 1. PROPERTY & OWNER SITUATION\n\nThis is a **brand-new construction structure play** with critical distress indicators. DCAD shows a 2025-built, 4,524 sqft home with current market value of $603,860—a recently completed spec build or custom home. The property transferred via deed on 8/31/2023, suggesting Elizabeth Ortalejo acquired raw land or a lot during construction phase. The 0.3184-acre lot in Martha P. Green Survey (Abstract 519) indicates urban infill development in established North Carrollton corridor. **Critical red flag: NO homestead exemption** on a property this size signals either investment intent, rental failure, or immediate post-construction financial collapse. The owner paid 2024 taxes but defaulted on 2025—pointing to acute financial distress beginning late 2025, possibly related to construction loan maturation, failed sale, or tenant default. Alex Rafael Ortalejo Espino as co-defendant suggests spouse or family partnership. DCAD shows live tax balance of $0.00 despite the lawsuit claiming $4,430.15 owed—this means either recent partial payment that hasn''t updated court records, or DCAD lag. The structure-to-total value ratio is essentially 100% given the 2025 build date, making this purely a **structure value play** with minimal land-only fallback position.\n\n## 2. FINANCIAL PICTURE\n\nThe filing amount of **$4,430.15** covers only two delinquency years (2024-2025) with CFBISD taxes dominating at $2,773.86 principal plus $1,306.29 in penalties/interest—a 47% penalty load indicating filing occurred approximately 12+ months after initial 2024 delinquency. However, DCAD live data shows **$0.00 current balance**, creating a critical intelligence gap: either Ortalejo made payment post-filing (May 2026 or later) that satisfied the taxing authorities but Linebarger continues pursuing legal fees/costs, or DCAD hasn''t synchronized with court records. Assuming the debt is actually satisfied at taxing entity level, the **live payoff cost today** would be minimal legal fees (estimate $2,000-$3,500 in Linebarger attorney fees','\n',char(10)),NULL,'pre_judgment',NULL,NULL,NULL,NULL,'2026-07-01T23:57:56.120068','2026-07-07T12:41:10.054892','2026-07-07T12:41:10.054892',1,'individual','high','BEING 0.3184 ACRES, MORE OR LESS, TRACT 19, OF THE MARTHA P. GREEN SURVEY, ABSTRACT 519, PAGE 255, AKA 1607 N. DENTON DRIVE, CITY OF CARROLLTON, TEXAS AS RECORDED IN INSTRUMENT 202300177640, OF THE DALLAS COUNTY DEED RECORDS','{"account_number": "65051925510190000", "market_value": 603860, "land_value": 100000, "improvement_value": 503860, "estimated_annual_taxes": 12196.01, "year_built": 2025, "effective_year_built": 2025, "actual_age": 1, "building_class": "21", "con