INSERT INTO cases VALUES(36,'TX-26-01379','44th District Court','GINSBERG, CARL','2026-07-06','OPEN','TAX DELINQUENCY','RUBY FAYE BROWN','[{"name": "Ruby Faye Brown", "address": "Address Unknown", "serviceStatus": "unserved", "serviceMethod": "Citation by Posting Requested", "isInRemOnly": false, "notes": "Citation by Posting Requested"}, {"name": "Felicia Denise Taylor", "address": "7930 Valencia Ct., Highland, CA 92346-5761", "serviceStatus": "unserved", "serviceMethod": "", "isInRemOnly": false, "notes": ""}, {"name": "The Unknown Shareholders, Successors, and Assigns of Mesquite NF SNF, LLC", "address": "Unknown", "serviceStatus": "unserved", "serviceMethod": "Citation by Posting Requested", "isInRemOnly": true, "notes": "Citation by Posting Requested; unknown heirs, successors and assigns"}]','',NULL,'00000324892000000','LGBS (Linebarger)','JONES, STEPHEN EARL',11437.289999999999956,NULL,'[]',3,1,0,'[]',0,0,0,'Citation by Posting requested for Ruby Faye Brown (address unknown) and unknown shareholders of Mesquite NF SNF, LLC','high',NULL,NULL,'none',NULL,0,'2027-03-01',NULL,NULL,NULL,'dallas',NULL,'[{"entity": "Dallas County", "taxAmt": 655.59, "penaltyInterest": 412.77, "total": 1068.36}, {"entity": "Parkland Hospital District", "taxAmt": 664.09, "penaltyInterest": 421.44, "total": 1085.53}, {"entity": "Dallas College", "taxAmt": 330.99, "penaltyInterest": 209.76, "total": 540.75}]',replace('# ACQUISITION INTELLIGENCE MEMO\n**PC PEAK DEVELOPMENT – CONFIDENTIAL**\n\n**Case:** TX-26-01379 | **Property Account:** 00000324892000000  \n**Primary Target:** Ruby Faye Brown (unserved, address unknown)  \n**Prepared:** January 2027 | **Analyst Priority:** HIGH\n\n---\n\n## 1. PROPERTY & OWNER SITUATION\n\nThis is a **structure play with significant distressed asset characteristics**. The 1947-built, 1,077 sqft property carries 60% depreciation on the DCAD rolls – positioning it at the inflection point where economic obsolescence meets teardown consideration. At 79 year