INSERT INTO cases VALUES(37,'TX-26-01377','44th District Court','GINSBERG, CARL','2026-07-06','OPEN','TAX DELINQUENCY','Texas Granite & Tile Co.','[{"name": "Texas Granite & Tile Co., A Texas Corporation", "address": "c/o Registered Agent Yadisely Luis, 1015 N I-35, Ste. 300, Carrollton, TX 75006", "serviceStatus": "unserved", "serviceMethod": "registered agent", "isInRemOnly": false, "notes": "Texas Corporation with registered agent service"}, {"name": "Unknown heirs, successors and assigns of Texas Granite & Tile Co.", "address": "Unknown", "serviceStatus": "unserved", "serviceMethod": "", "isInRemOnly": true, "notes": "Identity and location unknown"}, {"name": "Unknown owners and all other persons including adverse claimants", "address": "Unknown", "serviceStatus": "unserved", "serviceMethod": "", "isInRemOnly": true, "notes": "Any persons owning or claiming legal or equitable interest in or lien upon the property"}]','',NULL,'99071031164000000','LGBS (Linebarger)','ZOKAIE, CHEYENNE MATHEW',9993.9000000000000056,NULL,'[]',3,0,0,'["TX-11-40235 - CARROLLTON-FARMERS BRANCH ISD vs. YYTGT, INC. D/B/A TEXAS GRANITE & TILE CO. - 38th District Court", "TX-20-00101 - CARROLLTON-FARMERS BRANCH ISD AND VALWOOD IMPROVEMENT AUTHORITY vs. YYTGT, INC. D/B/A TEXAS GRANITE AND TILE - 192nd District Court"]',0,0,0,'Registered agent service required; unknown heirs and claimants','medium',NULL,NULL,'none',NULL,0,'2027-03-01',NULL,NULL,NULL,'dallas',NULL,'[{"entity": "Dallas County", "taxAmt": 1102.11, "penaltyInterest": 708.11, "total": 1810.22}, {"entity": "Parkland Hospital District", "taxAmt": 1129.59, "penaltyInterest": 733.35, "total": 1862.94}, {"entity": "Dallas College", "taxAmt": 561.84, "penaltyInterest": 363.99, "total": 925.83}]',replace('# ACQUISITION INTELLIGENCE MEMO\n\n**CASE:** TX-26-01377 | **ENTITY:** Texas Granite & Tile Co. | **FILED:** July 6, 2026  \n**ANALYST:** Senior Acquisition Team | **DATE:** January 2025  \n**PRIORITY:** HIGH – Corporate Abandonment Play\n\n---\n\n## 1. PROPERTY & OWNER SITUATION\n\nThis is a **pure land/location play** with severe ownership complications. The property carries a homestead exemption under Texas Granite & Tile Co., which is highly irregular for a commercial entity and suggests either fraudulent exemption claiming or a defunct business structure masking individual ownership. The $100,730 market value with $59,656.50 in live tax debt (59% debt-to-value ratio) indicates DCAD is valuing raw land or a minimal improvement scenario—no building age, square footage, or exterior data appears in county records, confirming this is either vacant land or a severely distressed/demolished structure. The company name suggests former commercial use (tile supplier/fabricator), likely abandoned when the business failed.\n\nCritical ownership intelligence: **Two prior tax suits** (TX-11-40235 in 2011 and TX-20-00101 in 2020) were filed by Carrollton-Farmers Branch ISD and Valwood Improvement Authority, with payment history showing "ATTY FEES" paid in 2011. This reveals a pattern—the entity or beneficial owner has fought off foreclosure twice before by paying attorney fees at the last moment, suggesting *someone* still monitors this asset and views it as worth saving despite 14 years of non-payment. The registered agent Yadisely Luis at 1015 N I-35, Carrollton (Suite 300—mail drop or service office) is unserved, and the defendant remains unserved 7+ months post-filing, indicating intentional evasion or true corporate death.\n\n---\n\n## 2. FINANCIAL PICTURE\n\nFiling amount of **$9,993.90** versus live balance of **$59,656.50** reveals catastrophic penalty acceleration—the debt has grown $49,662.60 (497% increase) since filing, likely due to: (1) compounding 12-15% annual penalties plus 1% monthly interest on 14 years of delinquency, (2) attorney fees from this and potentially prior suits, and (3) accumulated ISD and hospital district obligations ballooning faster than county taxes. Breaking down the filing amount: Dallas County $1,810.22, Parkland Hospital $1,862.94, Dallas College $925.83—these three entities alone total $4,','\n',char(10)),NULL,'pre_judgment',NULL,NULL,NULL,NULL,'2026-07-07T12:39:54.566900','2026-07-07T12:39:54.566900','2026-07-07T12:39:54.566900',1,'individual','high','','{"account_number": "99071031164000000", "market_value": 100730, "land_value": 0, "improvement_value": 100730, "estimated_annual_taxes": 0.0, "year_built": null, "effective_year_built": null, "actual_age": null, "building_class": "", "construction_type": "", "foundation": "", "roof_type": "", "roof_material": "", "exterior_wall": "", "living_area_sqft": null, "total_area_sqft": null, "bedrooms": null, "bathrooms": "", "stories": "", "depreciation_pct": null, "desirability": "", "air_condition": "", "heating": "", "garage_sqft": null, "zoning": "", "lot_frontage_ft": null, "lot_depth_ft": null, "lot_area_sqft": null, "land_unit_price": null, "legal_description": "1: TEXAS GRANITE & TILE CO 2: 3: 4: 5: Deed Transfer Date:", "owners": [{"name": "TEXAS GRANITE & TILE CO", "pct": 100}], "deed_transfer_date": "", "exemptions": "City\tSchool\tCounty\tCollege\tHospital\tSpecial District", "no_homestead": false, "tax_rates": [{"entity": "DALLAS COUNTY\tDALLAS COLLEGE\tPARKLAND HOSPITAL\tVALWOOD IMPROVEMENT AUTHORITY\nBPP EXEMPTION", "estimated_tax": 100730.0}], "current_tax_balance": 59656.5, "current_levy": 1231.66, "prior_year_due": 57912.47, "payment_history": [{"date": "2012-12-19", "amount": 35.49, "tax_year": "2011", "payer": "ATTY FEES"}, {"date": "2012-12-19", "amount": 35.15, "tax_year": "2011", "payer": "ATTY FEES"}], "tax_by_year": [], "distress": {"score": 3, "level": "moderate", "signals": [{"type": "payment_gap", "label": "No tax payment for 14 years \u2014 owner disengaged", "severity": "critical"}]}, "street_view_url": "", "dcad_url": "https://www.dallascad.org/AcctDetailRes.aspx?ID=99071031164000000", "act_url": "https://www.dallasact.com/act_webdev/dallas/showdetail2.j