PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE cases (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            case_number     TEXT UNIQUE NOT NULL,
            court           TEXT,
            judicial_officer TEXT,
            filed_date      TEXT,
            case_status     TEXT DEFAULT 'OPEN',
            case_type       TEXT DEFAULT 'TAX DELINQUENCY',
            defendant       TEXT,
            all_defendants  TEXT,  -- JSON array
            property_address TEXT,
            property_legal  TEXT,
            account_number  TEXT,
            law_firm        TEXT,
            plaintiff_attorney TEXT,
            total_due_filing REAL,
            oldest_delinquency_year INTEGER,
            delinquency_years TEXT, -- JSON array
            def_count       INTEGER DEFAULT 1,
            cbp_requested   INTEGER DEFAULT 0,
            rule106         INTEGER DEFAULT 0,
            prior_suits     TEXT,  -- JSON array
            estate_heir     INTEGER DEFAULT 0,
            continuance_count INTEGER DEFAULT 0,
            trial_reset_count INTEGER DEFAULT 0,
            service_issues  TEXT,
            complexity      TEXT DEFAULT 'medium',
            complexity_reason TEXT,
            judgment_date   TEXT,
            judgment_type   TEXT,
            oos_date        TEXT,
            oos_issued      INTEGER DEFAULT 0,
            next_hearing_date TEXT,
            notice_judgment_date TEXT,
            projected_oos   TEXT,
            confidence_pct  INTEGER,
            city            TEXT DEFAULT 'dallas',
            petition_pdf_path TEXT,
            tax_breakdown   TEXT,  -- JSON array
            ai_memo         TEXT,
            similar_benchmark TEXT,
            stage           TEXT DEFAULT 'pre_judgment',
            assessed_value  REAL,
            minimum_bid     REAL,
            sale_scheduled_date TEXT,
            sale_pulled_date TEXT,
            created_at      TEXT DEFAULT (datetime('now')),
            updated_at      TEXT DEFAULT (datetime('now')),
            last_agent_run  TEXT,
            monitored       INTEGER DEFAULT 1
        , owner_type TEXT, owner_priority TEXT, legal_description TEXT, property_intel TEXT);
CREATE TABLE docket_events (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            case_number TEXT NOT NULL,
            event_date  TEXT,
            event_type  TEXT,
            description TEXT,
            detail      TEXT,
            is_new      INTEGER DEFAULT 0,
            created_at  TEXT DEFAULT (datetime('now')),
            FOREIGN KEY (case_number) REFERENCES cases(case_number)
        );
CREATE TABLE agent_runs (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            started_at      TEXT DEFAULT (datetime('now')),
            finished_at     TEXT,
            status          TEXT DEFAULT 'running',
            cases_processed INTEGER DEFAULT 0,
            cases_updated   INTEGER DEFAULT 0,
            new_events_found INTEGER DEFAULT 0,
            errors          TEXT,
            log             TEXT
        );
CREATE TABLE watch_list (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            case_number TEXT UNIQUE NOT NULL,
            added_at    TEXT DEFAULT (datetime('now')),
            added_by    TEXT DEFAULT 'manual',
            notes       TEXT
        );
CREATE TABLE benchmarks (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            case_number     TEXT UNIQUE NOT NULL,
            description     TEXT,
            city            TEXT,
            complexity      TEXT,
            def_count       INTEGER,
            filed_date      TEXT,
            judgment_date   TEXT,
            judgment_type   TEXT,
            oos_date        TEXT,
            filing_to_judgment_months INTEGER,
            judgment_to_oos_days INTEGER,
            total_due       REAL,
            delinquency_years INTEGER,
            stage           TEXT,
            key_factors     TEXT,  -- JSON array
            outcome         TEXT,
            is_confirmed    INTEGER DEFAULT 0
        );
CREATE TABLE test (id INTEGER);
CREATE TABLE prospects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    account_number TEXT UNIQUE, owner_name TEXT, owner_type TEXT,
    owner_priority TEXT, courts_search_name TEXT, property_address TEXT,
    total_due REAL, current_due REAL, prior_due REAL, appraised_value REAL,
    homestead INTEGER DEFAULT 0, over65 INTEGER DEFAULT 0, veteran INTEGER DEFAULT 0,
    bankruptcy_number TEXT, tax_suit_number TEXT DEFAULT "",
    has_suit INTEGER DEFAULT 0, property_url TEXT, contact_approach TEXT, added_date TEXT, appraisal_url TEXT, acquisition_note TEXT, last_checked TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_cases_status ON cases(case_status);
CREATE INDEX idx_cases_stage ON cases(stage);
CREATE INDEX idx_events_case ON docket_events(case_number);
COMMIT;
